const A=require('node:assert/strict'),Q=require('./aquatic'),V=require('./vertebrates');let tests=[],results={};function test(n,f){f();tests.push(n)}function run(s,n){let max=0;for(let i=0;i<n;i++){Q.tick(s);for(const v of Object.values(s.last)){A.ok(Number.isFinite(v)&&Math.abs(v)<1e-6,JSON.stringify(s.last));max=Math.max(max,Math.abs(v))}for(const r of s.aqua){A.ok(r.o>=0&&r.o<=1&&r.n>=0&&r.p>=0);for(const k of Q.names)for(const x of Object.values(r[k]))A.ok(x>=-1e-12)}}return max;}
test('28 trechos e fauna inicial preservada',()=>{let s=Q.create();A.equal(s.aqua.length,28);A.deepEqual(s.animals,V.create().animals)});
test('determinismo e serialização',()=>{let s=Q.create();run(s,8);let t=JSON.parse(JSON.stringify(s));run(s,8);run(t,8);A.deepEqual(s,t)});
test('luz controla fixação',()=>{let a=Q.create(),b=Q.create();b.light='dark';run(a,8);run(b,8);A.ok(a.aquaEvents.fixed>0);A.equal(b.aquaEvents.fixed,0)});
test('peixe consome invertebrados',()=>{let s=Q.create();run(s,12);A.ok(s.aquaEvents.fishMeals>0&&s.aquaEvents.decomp>0)});
test('escoamento conecta terra e rio',()=>{let s=Q.create();s.weather='storm';run(s,12);A.ok(s.aquaEvents.landC>0&&s.aquaEvents.landN>0&&s.aquaEvents.landP>0)});
test('excesso de matéria orgânica reduz oxigênio',()=>{let a=Q.create(),b=Q.create();a.weather=b.weather='rain';for(let i=0;i<12;i++)Q.edit(b,12,'organic');run(a,12);run(b,12);A.ok(b.aqua[12].o<a.aqua[12].o);results.oxygen={control:a.aqua[12].o,organic:b.aqua[12].o}});
test('pesca e aportes contabilizados',()=>{let s=Q.create(),b=Q.totals(s),l={...s.ledger};Q.edit(s,5,'fish');Q.edit(s,5,'nutrients');Q.edit(s,5,'organic');let a=Q.totals(s);for(const [k,ik,ok] of [['c','externalC','carbonOut'],['n','externalN','nOut'],['p','externalP','pOut']])A.ok(Math.abs(a[k]-b[k]-(s.ledger[ik]-(l[ik]||0))+(s.ledger[ok]-l[ok]))<1e-8)});
for(const w of ['auto','drought','storm'])test('30 dias '+w,()=>{let s=Q.create();s.weather=w;let max=run(s,120);results[w]={max,...Q.metrics(s),events:s.aquaEvents,land:V.metrics(s)}});console.log(JSON.stringify({passed:tests.length,tests,results},null,2));
